const size_t sgi_model_entry_count = ARRAY_SIZE(sgi_model_entries);

/*
 * One default topology per product: the shipped single-node Origin 200
 * and the four-node compute module the Origin 2000 boots today. Every
 * other entry (the dual-module Origin 200) is reached only by naming it
 * with topology=.
 */
const char *sgi_model_default_topology(const char *product)
{
    if (!strcmp(product, "origin200")) {
        return "origin200";
    }
    if (!strcmp(product, "origin2000")) {
        return "origin2000-module";
    }
    return NULL;
}

const SGIModelTopology *sgi_model_find_topology(const char *name)
{
    size_t i;

    for (i = 0; i < sgi_model_entry_count; i++) {
        if (!strcmp(name, sgi_model_entries[i].name)) {
            return &sgi_model_entries[i];
        }
    }
    return NULL;
}
